MAP
  #CONFIG "MS_ERRORFILE" "stdout"
  #CONFIG "PROJ_LIB" "D:/MapServer/bin/nad/"
  EXTENT -78000 6448000 1116000 7940000
  FONTSET   "/etc/mapserver/bin/maps/fonts/fonts.txt"
  IMAGECOLOR 125 125 125
  IMAGETYPE "png"
  MAXSIZE 12000
  NAME "LKM"
  SHAPEPATH "/etc/mapserver/bin/kartdata/la/data/"
  SIZE 1028 737
  STATUS ON
  UNITS METERS

  OUTPUTFORMAT
    NAME "png"
    MIMETYPE "image/png"
    DRIVER "AGG/PNG"
    EXTENSION "png"
    IMAGEMODE RGB
    TRANSPARENT FALSE
    FORMATOPTION "GAMMA=0.75"
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "application/json"
    DRIVER "OGR/GEOJSON"
    MIMETYPE "application/json"
    FORMATOPTION "FORM=SIMPLE"
    FORMATOPTION "STORAGE=memory"
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "gif"
    MIMETYPE "image/gif"
    DRIVER "AGG/PNG8"
    EXTENSION "gif"
    IMAGEMODE RGB
    TRANSPARENT FALSE
    FORMATOPTION "QUANTIZE_FORCE=on"
    FORMATOPTION "QUANTIZE_COLORS=256"
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "png8"
    MIMETYPE "image/png; mode=8bit"
    DRIVER "AGG/PNG8"
    EXTENSION "png"
    IMAGEMODE RGB
    TRANSPARENT FALSE
    FORMATOPTION "QUANTIZE_FORCE=on"
    FORMATOPTION "QUANTIZE_COLORS=256"
    FORMATOPTION "GAMMA=0.75"
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "jpeg"
    MIMETYPE "image/jpeg"
    DRIVER "AGG/JPEG"
    EXTENSION "jpg"
    IMAGEMODE RGB
    TRANSPARENT FALSE
    FORMATOPTION "GAMMA=0.75"
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "svg"
    MIMETYPE "image/svg+xml"
    DRIVER "CAIRO/SVG"
    EXTENSION "svg"
    IMAGEMODE RGB
    TRANSPARENT FALSE
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "pdf"
    MIMETYPE "application/x-pdf"
    DRIVER "CAIRO/PDF"
    EXTENSION "pdf"
    IMAGEMODE RGB
    TRANSPARENT FALSE
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "GTiff"
    MIMETYPE "image/tiff"
    DRIVER "GDAL/GTiff"
    EXTENSION "tif"
    IMAGEMODE RGB
    TRANSPARENT FALSE
  END # OUTPUTFORMAT

  OUTPUTFORMAT
    NAME "cairopng"
    MIMETYPE "image/png"
    DRIVER "CAIRO/PNG"
    EXTENSION "png"
    IMAGEMODE RGB
    TRANSPARENT FALSE
  END # OUTPUTFORMAT

  PROJECTION
    "init=epsg:25833"
  END # PROJECTION
  LEGEND
    KEYSIZE 16 10
    KEYSPACING 5 5
    LABEL
      FONT "arial"
      SIZE 8
      COLOR 1 1 1
      OFFSET 0 0
      SHADOWSIZE 1 1
    END # LABEL
    STATUS ON
    TRANSPARENT TRUE
  END # LEGEND

  QUERYMAP
    SIZE 200 200
    STATUS OFF
    STYLE HILITE
  END # QUERYMAP

  SCALEBAR
    INTERVALS 4
    LABEL
      SIZE 10
      OFFSET 0 0
      SHADOWSIZE 1 1
    END # LABEL
    SIZE 200 3
    STATUS OFF
    UNITS MILES
  END # SCALEBAR

  WEB
    IMAGEPATH "/etc/MapServer/bin/maps/output/"
    IMAGEURL "/etc/mapserver/bin/maps/output/"
    METADATA
