  LAYER

    METADATA
      "wms_extent"	"-78000 6448000 1116000 7940000"
      "wfs_extent" "-78000 6448000 1116000 7940000"
      "wfs_use_default_extent_for_getfeature" "false"
      "ows_enable_request" "*"
      "wfs_enable_request" "*"
      "wms_enable_request" "*"
      "gml_include_items"	"all"
      "ows_include_items"	"all"
      "wms_include_items"	"all"
      "wms_title"	"Målestokk >= 1:500k"
      "wfs_title" "Bioklimatiske seksjoner"
      "wfs_srs" "EPSG:25833"
      "gml_featureid" "gpkg_fid"
      "oga_enable" "true"
      "oga_crs_default" "EPSG:25833"
      "ows_group_title" "Bioklimatiske seksjoner"
    END # METADATA

    NAME "Seksjoner_malestokk_over_500k"
    GROUP "Bioklimatiske seksjoner"
    STATUS ON
    TYPE POLYGON
    CONNECTIONTYPE OGR
    CONNECTION "bioklimatiske_seksjoner_2026.gpkg"
    DATA "SELECT fid as gpkg_fid, * FROM seksjoner_copy"
    HEADER "etc/mapserver/bin/maps/query/lkm_2026_soner_header.html"
    TEMPLATE "etc/mapserver/bin/maps/query/lkm_2026_soner_body.html"
    PROJECTION
        "init=epsg:25833" # Match your data's projection
    END #Projection
    EXTENT -78000 6448000 1116000 7940000
    CLASS
      NAME "Sterkt oseanisk seksjon"
      EXPRESSION ('[se_value]' = '1')
      STYLE
        COLOR '#120dfa'
      END # STYLE
      MAXSCALEDENOM 500000
    END # CLASS
    CLASS
      NAME "Klart oseanisk seksjon"
      EXPRESSION ('[se_value]' = '2')
      STYLE
        COLOR '#3c63fe'
      END # STYLE
      MAXSCALEDENOM 500000
    END # CLASS
    CLASS
      NAME "Svak oseanisk seksjon"
      EXPRESSION ('[se_value]' = '3')
      STYLE
        COLOR '#66a5fe'
      END # STYLE
      MAXSCALEDENOM 500000
    END # CLASS
    CLASS
      NAME "Overgangsseksjon"
      EXPRESSION ('[se_value]' = '4')
      STYLE
        COLOR '#91d2fe'
      END # STYLE
      MAXSCALEDENOM 500000
    END # CLASS
    CLASS
      NAME "Svak kontinental seksjon"
      EXPRESSION ('[se_value]' = '5')
      STYLE
        COLOR '#bcf4fe'
      END # STYLE
      MAXSCALEDENOM 500000
    END # CLASS
  END # LAYER

    LAYER
    METADATA  
      "wms_title" "Målestokk < 1:500k"
      "wms_include_items"	"value_0"
      "wms_extent"	"-78000 6448000 1116000 7940000"
      "ows_enable_request"	"*"
      "gml_include_items"	"value_0"
      "oga_enable" "false"
    END
    GROUP "Bioklimatiske seksjoner"
    NAME "Seksjoner_malestokk_under_500k"
    TYPE RASTER
    STATUS ON
    MINSCALEDENOM 500000
    DATA "sections.tif"
    PROJECTION
        "init=epsg:25833" # Match your data's projection
    END
  END


